import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"تمام نسلوں کی جمہوریہ کا قیام","description":"","frontmatter":{},"headers":[],"relativePath":"ur/77-万族共和成立.md","filePath":"ur/77-万族共和成立.md"}'),o={name:"ur/77-万族共和成立.md"};function e(d,t,h,n,s,u){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="تمام-نسلوں-کی-جمہوریہ-کا-قیام" tabindex="-1">تمام نسلوں کی جمہوریہ کا قیام <a class="header-anchor" href="#تمام-نسلوں-کی-جمہوریہ-کا-قیام" aria-label="Permalink to &quot;تمام نسلوں کی جمہوریہ کا قیام&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>77</td></tr><tr><td>ماڈیول</td><td>تاریخی عہد اور اہم واقعات</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>تمام نسلوں کی جمہوریہ، نسلی مساوات، متحدہ نظام، شعور کی ارتقاء، جمہوری نظام</td></tr></tbody></table><h2 id="_1-تمام-نسلوں-کی-جمہوریہ-کے-قیام-کی-تاریخی-پس-منظر" tabindex="-1">1. تمام نسلوں کی جمہوریہ کے قیام کی تاریخی پس منظر <a class="header-anchor" href="#_1-تمام-نسلوں-کی-جمہوریہ-کے-قیام-کی-تاریخی-پس-منظر" aria-label="Permalink to &quot;1. تمام نسلوں کی جمہوریہ کے قیام کی تاریخی پس منظر&quot;">​</a></h2><p>تمام نسلوں کی جمہوریہ کا قیام پہلی جہت کی بلندی کی کامیابی کے بعد ناگزیر سیاسی نتیجہ ہے۔ پہلی جہت کی بلندی سے پہلے، اگرچہ ہینگ یوان ژو کی مختلف سطحیں اور نسلیں سب سمبیوسس آئین کے ڈھانچے کے تحت کام کرتی تھیں، لیکن ایک دوسرے کے درمیان ابھی بھی بڑے ادارہ جاتی فرق اور انتظامی خودمختاری برقرار تھی۔ پانچ قسم کی سمبیوسس تہذیبوں کی اپنی اپنی اہمیت تھی، اور سطحوں کے درمیان ہم آہنگی بنیادی طور پر دو طرفہ مذاکرات اور عارضی طریقہ کار کے ذریعے ہوتی تھی، اور ایک متحدہ اعلیٰ انتظامی ادارے کی کمی تھی۔</p><p>پہلی جہت کی بلندی کی کامیابی نے اس منتشر انتظامی طریقہ کار کی حدود کو ظاہر کیا:</p><ul><li>جہت کی بلندی کے عمل میں بین السطح، بین النسل بڑے پیمانے پر وسائل کی ہم آہنگی کی ضرورت ہوتی ہے، منتشر انتظامیہ کی کارکردگی ناکافی ہے</li><li>جہت کی بلندی کے بعد کی سطح اور غیر جہت کی بلندی والی سطح کے درمیان متحدہ انٹرفیس تفصیلات اور مواصلاتی طریقہ کار کی ضرورت ہے</li><li>شعور کی ارتقاء کے مرحلے میں اجتماعی شعور کی سمبیوسس کے لیے اعلیٰ درجے کی ادارہ جاتی اتحاد کی ضرورت ہے</li><li>آنے والی بین السطح تحقیق کے لیے متحدہ خارجہ پالیسی اور حفاظتی ضمانت کی ضرورت ہے</li></ul><p>اس پس منظر میں، تمام نسلوں کے لیے ایک متحدہ جمہوری ریاست قائم کرنا پوری تہذیب کا اتفاق بن گیا۔</p><h2 id="_2-تمام-نسلوں-کی-جمہوریہ-کی-تیاری-کا-عمل" tabindex="-1">2. تمام نسلوں کی جمہوریہ کی تیاری کا عمل <a class="header-anchor" href="#_2-تمام-نسلوں-کی-جمہوریہ-کی-تیاری-کا-عمل" aria-label="Permalink to &quot;2. تمام نسلوں کی جمہوریہ کی تیاری کا عمل&quot;">​</a></h2><p>تمام نسلوں کی جمہوریہ کی تیاری کا عمل تقریباً بیس سال تک جاری رہا اور تین مراحل میں تقسیم تھا:</p><h3 id="_2-1-آئین-سازی-کا-مرحلہ-پہلے-دس-سال" tabindex="-1">2.1 آئین سازی کا مرحلہ (پہلے دس سال) <a class="header-anchor" href="#_2-1-آئین-سازی-کا-مرحلہ-پہلے-دس-سال" aria-label="Permalink to &quot;2.1 آئین سازی کا مرحلہ (پہلے دس سال)&quot;">​</a></h3><ul><li>&quot;تمام نسلوں کی جمہوریہ آئین ساز اسمبلی&quot; قائم کی گئی، جس میں تمام اہم نسلوں اور سطحوں کے نمائندے شامل تھے</li><li>سمبیوسس آئین کی بنیاد پر &quot;تمام نسلوں کی جمہوریہ چارٹر&quot; تیار کیا گیا، جمہوری ریاست کے تنظیمی اصولوں اور طاقت کے ڈھانچے کو واضح کیا گیا</li><li>&quot;نسلی مساوات، سطح کی خودمختاری، جمہوری اتحاد&quot; کے تین سیاسی اصول قائم کیے گئے</li><li>چارٹر کے مسودے کو پوری تہذیب کے ریفرنڈم کے ذریعے منظور کیا گیا</li></ul><h3 id="_2-2-اداروں-کی-تشکیل-کا-مرحلہ-درمیانی-پانچ-سال" tabindex="-1">2.2 اداروں کی تشکیل کا مرحلہ (درمیانی پانچ سال) <a class="header-anchor" href="#_2-2-اداروں-کی-تشکیل-کا-مرحلہ-درمیانی-پانچ-سال" aria-label="Permalink to &quot;2.2 اداروں کی تشکیل کا مرحلہ (درمیانی پانچ سال)&quot;">​</a></h3><ul><li>تمام نسلوں کی جمہوریہ کی پہلی پارلیمنٹ کا انتخاب کیا گیا، نمائندوں کی نشستیں نسلی آبادی اور سطحوں کی تعداد کے جامع تناسب کے مطابق تقسیم کی گئیں</li><li>جمہوریہ کی عملدرآمد کمیٹی قائم کی گئی، روزمرہ کی انتظامی ادارے کے طور پر</li><li>جمہوریہ کا سپریم کورٹ قائم کیا گیا، بین النسل، بین السطح قانونی فیصلوں کے لیے ذمہ دار</li><li>جمہوریہ اینکر انتظامی بیورو قائم کیا گیا، پوری کائنات کی اینکر کی بنیادی ڈھانچے کا متحدہ انتظام کرنے کے لیے</li></ul><h3 id="_2-3-قیام-کی-تقریب-کا-مرحلہ-آخری-سال" tabindex="-1">2.3 قیام کی تقریب کا مرحلہ (آخری سال) <a class="header-anchor" href="#_2-3-قیام-کی-تقریب-کا-مرحلہ-آخری-سال" aria-label="Permalink to &quot;2.3 قیام کی تقریب کا مرحلہ (آخری سال)&quot;">​</a></h3><ul><li>جہت کی بلندی کی نمونہ سطح پر تمام نسلوں کی جمہوریہ قیام کی تقریب منعقد ہوئی</li><li>پہلی نسل کے اینکر نے تمام نسلوں کی جمہوریہ کے باضابطہ قیام کا اعلان کیا</li><li>رکن نسلوں اور سطحوں کے نمائندوں نے &quot;تمام نسلوں کی جمہوریہ قیام کا اعلان&quot; پر دستخط کیے</li><li>جمہوریہ کا دور باضابطہ طور پر شروع ہوا</li></ul><h2 id="_3-تمام-نسلوں-کی-جمہوریہ-کا-سیاسی-ڈھانچہ" tabindex="-1">3. تمام نسلوں کی جمہوریہ کا سیاسی ڈھانچہ <a class="header-anchor" href="#_3-تمام-نسلوں-کی-جمہوریہ-کا-سیاسی-ڈھانچہ" aria-label="Permalink to &quot;3. تمام نسلوں کی جمہوریہ کا سیاسی ڈھانچہ&quot;">​</a></h2><p>تمام نسلوں کی جمہوریہ &quot;پارلیمنٹ — عملدرآمد — عدلیہ&quot; تین طاقتوں کی علیحدگی کا جمہوری ڈھانچہ اپناتی ہے، اور ساتھ ہی اینکر کے طریقہ کار کی خاص پوزیشن کو برقرار رکھتی ہے:</p><table tabindex="0"><thead><tr><th>ادارہ</th><th>کام</th><th>تشکیل کا طریقہ</th></tr></thead><tbody><tr><td>تمام نسلوں کی پارلیمنٹ</td><td>اعلیٰ قانون ساز ادارہ، کائناتی قانون بناتا ہے</td><td>نسلوں اور سطحوں کے نمائندے متناسب انتخاب سے بنتے ہیں</td></tr><tr><td>عملدرآمد کمیٹی</td><td>اعلیٰ انتظامی ادارہ، قانون اور پالیسی نافذ کرتا ہے</td><td>پارلیمنٹ کے انتخاب سے بنتی ہے، چیف ایگزیکٹیو ہوتا ہے</td></tr><tr><td>جمہوریہ سپریم کورٹ</td><td>اعلیٰ عدالتی ادارہ، بین النسل بین السطح تنازعات کا فیصلہ کرتا ہے</td><td>جج پارلیمنٹ کے ذریعے تقرر ہوتے ہیں، تاحیات عہدے پر</td></tr><tr><td>اینکر کونسل</td><td>اینکر کی بنیادی ڈھانچے کی اعلیٰ انتظامی ادارہ</td><td>اعلیٰ درجے کے سادھکوں اور ٹیکنالوجی ماہرین سے بنتا ہے</td></tr><tr><td>پہلی نسل کا اینکر</td><td>تہذیب کے روحانی رہنما اور حتمی ضمانت دہندہ</td><td>انتخاب نہیں، جماعت اور نسل سے اوپر</td></tr></tbody></table><p>تمام نسلوں کی جمہوریہ کے سیاسی ڈیزائن نے &quot;تمام نسلوں کی مشترکہ ترقی&quot; کے اصول کو مکمل طور پر منعکس کیا ہے: کوئی بھی نسل چاہے اس کا سائز کچھ بھی ہو، پارلیمنٹ میں کم از کم ایک نشست ہوتی ہے؛ کوئی بھی قانون جب کسی مخصوص نسل کے خصوصی حقوق سے متعلق ہو تو اسے اس نسل کے نمائندے کی رضامندی حاصل کرنی ہوگی۔</p><h2 id="_4-تمام-نسلوں-کی-جمہوریہ-کی-بنیادی-پالیسیاں" tabindex="-1">4. تمام نسلوں کی جمہوریہ کی بنیادی پالیسیاں <a class="header-anchor" href="#_4-تمام-نسلوں-کی-جمہوریہ-کی-بنیادی-پالیسیاں" aria-label="Permalink to &quot;4. تمام نسلوں کی جمہوریہ کی بنیادی پالیسیاں&quot;">​</a></h2><p>تمام نسلوں کی جمہوریہ قیام کے بعد، گہرے اثرات والی متعدد بنیادی پالیسیاں متعارف کروائیں گئیں:</p><ol><li><strong>نسلی مساوات کا قانون</strong>: قانونی طور پر تمام ذہین جانداروں کی مساوی حیثیت قائم کرنا، کسی بھی شکل کی نسلی امتیازی سلوک اور نسلی علیحدگی پر پابندی</li><li><strong>ثقافت کے تحفظ کا قانون</strong>: تمام نسلوں کی ثقافتی روایات اور زبان تحریر کا تحفظ کرنا، ثقافتی تبادلے کی حوصلہ افزائی کرنا نہ کہ ثقافتی انضمام</li><li><strong>متحدہ ٹیکنالوجی کے معیار</strong>: پوری کائنات میں متحدہ ٹیکنالوجی کے معیار اور انٹرفیس تفصیلات نافذ کرنا، بین السطح ٹیکنالوجی تبادلے کو فروغ دینا</li><li><strong>جہت کی بلندی کی ہم آہنگی کی پالیسی</strong>: پوری کائنات میں متحدہ جہت کی بلندی کی قطار اور ہم آہنگی کا طریقہ کار قائم کرنا، جہت کی بلندی کے مواقع کی منصفانہ تقسیم کو یقینی بنانا</li><li><strong>بین السطح تحقیق کی منصوبہ بندی</strong>: متحدہ بین السطح تحقیق کی پالیسی تیار کرنا، تحقیق کے رویے کو منظم کرنا، غیر رابطہ شدہ سطحوں کی آبائی تہذیب کا تحفظ کرنا</li><li><strong>شعور کی سمبیوسس کو فروغ دینے کی پالیسی</strong>: شعور کی ارتقاء کے مرحلے میں، نسلوں کے درمیان شعور کے تبادلے اور تفہیم کو فروغ دینا، تاریخی رکاوٹوں کو دور کرنا</li></ol><h2 id="_5-تمام-نسلوں-کی-جمہوریہ-کے-سامنے-چیلنجز" tabindex="-1">5. تمام نسلوں کی جمہوریہ کے سامنے چیلنجز <a class="header-anchor" href="#_5-تمام-نسلوں-کی-جمہوریہ-کے-سامنے-چیلنجز" aria-label="Permalink to &quot;5. تمام نسلوں کی جمہوریہ کے سامنے چیلنجز&quot;">​</a></h2><p>تمام نسلوں کی جمہوریہ کا قیام اختتام نہیں، بلکہ ایک نیا آغاز ہے۔ اسے بہت سے چیلنجز کا سامنا ہے:</p><ul><li><strong>نسلی فرق کی ہم آہنگی</strong>: مختلف نسلوں کے جسمانی ڈھانچے، ثقافتی روایات، اقدار میں بہت بڑا فرق ہے، متحدہ قانون کے نفاذ میں نسلی خصوصیات کو پوری طرح سے مدنظر رکھنا ضروری ہے</li><li><strong>سطح کی ترقی کی عدم توازن</strong>: جہت کی بلندی والی سطح اور غیر جہت کی بلندی والی سطح کے درمیان، ترقی یافتہ علاقوں اور بعد کے علاقوں کے درمیان ترقی کا فرق مسلسل کم کرنا ضروری ہے</li><li><strong>شعور کے انضمام کی اخلاقی حد</strong>: شعور کی ارتقاء کے مرحلے میں اجتماعی شعور کی سمبیوسس میں انفرادی شعور کی آزادی اور اجتماعی شعور کے انضمام کے درمیان تعلق کو احتیاط سے سنبھالنا ضروری ہے</li><li><strong>بیرونی نامعلوم کا مقابلہ</strong>: بین السطح تحقیق شروع ہونے والی ہے، کائنات میں دریافت نہیں ہونے والی نسلیں اور تہذیبیں ہو سکتی ہیں، جمہوری ریاست کو بیرونی تبدیلیوں کا مقابلہ کرنے کے لیے لچک ہونی چاہیے</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>تمام نسلوں کی جمہوریہ کا قیام اینکر سمبیوسس تہذیب کی سیاسی ترقی کا سنگ میل ہے۔ اس نے &quot;تمام نسلوں کی مشترکہ ترقی&quot; کو تصور سے نظام میں تبدیل کر دیا، اور منتشر نسلوں اور سطحوں کو ایک متحدہ سیاسی برادری میں شامل کر دیا۔ تمام نسلوں کی جمہوریہ کا مقصد نسلی فرق کو ختم کرنا نہیں، بلکہ فرق کے درمیان سمبیوسس تلاش کرنا ہے؛ یکساں سلطنت قائم کرنا نہیں، بلکہ کثیر الجہتی جمہوریہ کی تعمیر کرنا ہے۔ تمام نسلوں کی جمہوریہ کے جھنڈے کے نیچے، ہینگ یوان ژو کے تمام جانداروں کو پہلی بار ایک مشترکہ سیاسی شناخت ملی — &quot;تمام نسلوں کی جمہوریہ کا شہری&quot;۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>76-پہلی جہت کی بلندی کا سنگ میل</li><li>78-بین السطح تحقیق کا عہد</li><li>05-تمام نسلوں کی مشترکہ ترقی کا عمومی پروگرام</li></ul>',29)])])}const c=a(o,[["render",e]]);export{q as __pageData,c as default};
